func _tick_level2(delta: float, ppos: Vector3) -> void:
	# the train moves first so the ride seats' anchors are fresh when the
	# toy tick reads them (it also hides itself whenever phase != "court")
	m._train_ref()._tick_train(delta, ppos)
	_tick_toys(delta, ppos)
	if m.mg_kind != "":
		m._tick_mg2d(delta)
		return
	if m.l2_cutscene_t >= 0.0:
		m._tick_cutscene(delta)
		return
	if String(m.g.get("phase", "court")) == "hall":
		m._tick_castle_rooms(delta)
		return
	var explicit_touch: bool = m.touch_uses_explicit_interactions()
	if _tick_ocean_kingdom_gates(ppos):
		return
	# crafted friends are alive: they scamper around, and run up to nuzzle +
	# purr when Roshan comes near
	_tick_crafted(delta, ppos)
	_tick_alpine_house_bonuses(delta, ppos)
	# Alpine cave: the cairns are the visual pointer and nearing the hidden mouth
	# adds a recorded voice hint. The warm star inside is the northern-world door.
	if m.g.has("alpine_secret_pos"):
		var cave_entrance: Vector3 = m.g["alpine_cave_entrance"]
		if (not bool(m.g.get("alpine_cave_hint", false))
			and cave_entrance.distance_to(ppos) < 34.0):
			m.g["alpine_cave_hint"] = true
			m.show_msg("Roshan", "Ooh! The snowy mountain sparkles lead to that star!", "pearl")
	# Cave star: leave-and-re-enter hysteresis prevents an immediate return
	# trip from bouncing Roshan between the two separately loaded worlds.
	if m.g.has("northern_portal_pos"):
		var north_pos: Vector3 = m.g["northern_portal_pos"]
		var north_rune: Label3D = m.g.get("northern_portal_rune") as Label3D
		if is_instance_valid(north_rune):
			north_rune.scale = Vector3.ONE * (1.0 + sin(float(m.g["t"]) * 2.4) * 0.08)
		var north_dist: float = north_pos.distance_to(ppos)
		if not bool(m.g.get("northern_portal_armed", true)):
			if north_dist > 16.0:
				m.g["northern_portal_armed"] = true
		elif not explicit_touch and north_dist < 8.0:
			m._enter_northern_kingdom()
			return
		if (not bool(m.g.get("northern_portal_hint", false)) and north_dist < 28.0):
			m.g["northern_portal_hint"] = true
			m.show_msg("Roshan", "A magic star! A new world is through there!", "pearl2")
	# night magic: shooting stars streak over the lagoon after bedtime
	if m.is_night:
		m.night_star_t -= delta
		if m.night_star_t <= 0.0:
			m.night_star_t = 5.0 + randf() * 7.0
			m._spawn_shooting_star(ppos)
	# Rainbow Road race — swim into either leg of the rainbow arch (right leg = reversed lap)
	# main owns the shared kart cooldown tick; do not count it down a second time here.
	m.bw_cool = maxf(0.0, m.bw_cool - delta)
	if m.galaxy_unlocked and m.bw_portal_pos != Vector3.ZERO:
		var bw_dist: float = Vector2(m.bw_portal_pos.x - ppos.x, m.bw_portal_pos.z - ppos.z).length()
		var bw_height: float = absf(m.bw_portal_pos.y - ppos.y)
		if not m.galaxy_gateway_armed:
			if bw_dist > 13.0 or bw_height > 14.0:
				m.galaxy_gateway_armed = true
		elif not explicit_touch and m.bw_cool <= 0.0 and m.kart_cool <= 0.0 and bw_dist < 9.0 and bw_height < 10.0:
			m.bw_cool = 10.0
			m.galaxy_gateway_armed = false
			m.kart_from = "level2"   # Galaxy return routing shares the race-origin state
			m.show_msg("Roshan", "To the Butterfly World! Wheee!")
			m._start_galaxy()
			return
	# the EMBER FORTRESS door at the rainbow junction: swimming in launches the
	# float race with the DOWNWARD ending (same leave-and-return hysteresis as
	# the galaxy gate above; the shared kart cooldown prevents double-starts)
	if m.ember_portal_pos != Vector3.ZERO:
		var em_dist: float = Vector2(m.ember_portal_pos.x - ppos.x, m.ember_portal_pos.z - ppos.z).length()
		var em_h: float = absf(m.ember_portal_pos.y - ppos.y)
		if not bool(m.g.get("ember_gate_hint", false)) and em_dist < 30.0 and em_h < 20.0:
			m.g["ember_gate_hint"] = true
			m.show_msg("Roshan", "Ooh... a dark spooky door! The go-kart road can dive DOWN to the volcano planet!", "pearl")
		if not m.ember_gateway_armed:
			if em_dist > 16.0 or em_h > 16.0:
				m.ember_gateway_armed = true
		elif not explicit_touch and m.kart_cool <= 0.0 and m.bw_cool <= 0.0 and em_dist < 10.0 and em_h < 12.0:
			m.bw_cool = 10.0
			m.ember_gateway_armed = false
			m.kart_float_dest = "ember"
			m.show_msg("Ember King", "So! You found my dark door... race the rainbow road DOWN to my fortress, if you dare!", "talk")
			m._start_kart_game(false, "float")
			return
	if m.kart_legA != Vector3.ZERO:
		# horizontal distance + generous height tolerance (same forgiving test as the fairy pond)
		var dA: float = Vector2(m.kart_legA.x - ppos.x, m.kart_legA.z - ppos.z).length()
		var dB: float = Vector2(m.kart_legB.x - ppos.x, m.kart_legB.z - ppos.z).length()
		# explicit one-time introduction when you first reach the rainbow
		if not bool(m.g.get("kart_intro", false)) and minf(dA, dB) < 48.0:
			m.g["kart_intro"] = true
			m.show_msg("Rainbow Road", "The rainbow road to ROSHAN GALAXY! Race the rainbow to reach the stars — each side goes a different way around!")
		if minf(dA, dB) < 48.0:
			m.hud_game.text = "Swim INTO the rainbow to race your go-kart!"
		var a_outside: bool = dA > 18.0 or absf(m.kart_legA.y - ppos.y) > 22.0
		var b_outside: bool = dB > 18.0 or absf(m.kart_legB.y - ppos.y) > 22.0
		if not m.kart_float_portals_armed:
			if a_outside and b_outside:
				m.kart_float_portals_armed = true
		elif not explicit_touch and m.kart_cool <= 0.0:
			if dA < 14.0 and absf(m.kart_legA.y - ppos.y) < 18.0:
				m._start_kart_game(false, "float")
				return
			if dB < 14.0 and absf(m.kart_legB.y - ppos.y) < 18.0:
				m._start_kart_game(true, "float")
				return
	for fd in m.g.get("l2_fish", []):
		var fn2: Node3D = fd["node"]
		if not is_instance_valid(fn2):
			continue
		fd["off"] = fmod(float(fd["off"]) + float(fd["spd"]) * delta, float(fd["len"]))
		var base: Vector3 = (fd["a"] as Vector3) + (fd["dir"] as Vector3) * float(fd["off"])
		var side: Vector3 = (fd["dir"] as Vector3).cross(Vector3.UP).normalized()
		var fp: Vector3 = base + side * float(fd["lane"])
		# swim a fixed height above the LOCAL carved floor (hills cross the rivers)
		fp.y = m.lagoon_h(fp.x, fp.z) + 2.4 + sin(float(m.g.get("t", 0.0)) * 3.0 + float(fd["off"])) * 0.4
		fn2.position = fp
		fn2.look_at(fp + (fd["dir"] as Vector3) * 2.0, Vector3.UP)
	var got := 0
	var nxt: Node3D = null
	for sd in m.l2_stars:
		if bool(sd["got"]):
			got += 1
			continue
		var star: Node3D = sd["node"]
		star.position.y += sin(float(m.g["t"]) * 2.0 + star.position.x) * 0.02
		star.rotate_z(delta * 0.8)
		star.scale = Vector3.ONE * (1.0 + sin(float(m.g["t"]) * 4.0) * 0.12)
		if nxt == null:
			nxt = star
		var d: float = star.position.distance_to(ppos)
		# gentle magnet so a 4yo who swims close gets pulled in
		if d < 32.0:
			m.player.position = m.player.position.lerp(star.position, minf(0.85, delta * 1.7 * (1.0 - d / 32.0)))
		if d < 14.0:
			sd["got"] = true
			var sidx: int = m.l2_stars.find(sd)
			if sidx >= 0 and sidx < m.l2_star_progress.size():
				m.l2_star_progress[sidx] = true
				m.stickers["_l2_star_%d" % sidx] = true
				m._write_save()
			got += 1
			m._sparkle_burst(star.position, Color(1.0, 0.9, 0.4))
			if m.chime != null:
				m.chime.pitch_scale = 1.0 + float(got) * 0.12
				m.chime.play()
			if m.voice != null:
				m.voice.pitch_scale = 1.0 + randf() * 0.2
				m._play_success_yay(m.voice.pitch_scale)
			star.visible = false
			if got >= 3:
				m._open_castle_door()
	if got >= 3 and not m.l2_open:
		m._open_castle_door()
	# fairy pond — fly the top-down sparkle dodger (active once the castle is open)
	# (the fairy flight now launches from the Fairy Fountain in the Butterfly
	# World — the courtyard pond stays as scenery)
	# the rainbow gateway always takes you back to the ocean
	m.mg_cool = maxf(0.0, m.mg_cool - delta)
	# Phase 1: pictures are OPTIONAL play — inert until the castle is open, so
	# the natural swim line to the Dream Stars can't hijack into a minigame and
	# wipe star progress. Tight 3.5 radius + 0.6s dwell = deliberate visits only.
	if not explicit_touch and m.mg_cool <= 0.0 and m.mg_kind == "" and m.l2_open:
		var dw: Dictionary = m.g.get("pic_dwell", {})
		for wp in m.wall_pics:
			var wpp: Vector3 = wp["pos"]
			var akey := String(wp["art"])
			if Vector2(wpp.x - ppos.x, wpp.z - ppos.z).length() < 3.5 and absf(wpp.y - ppos.y) < 9.0:
				dw[akey] = float(dw.get(akey, 0.0)) + delta
				if float(dw[akey]) >= 0.6:
					dw[akey] = 0.0
					m.g["pic_dwell"] = dw
					if akey == "p_slide":
						m._l2_start_slide()
					else:
						m._mg2d_open(String(m.PIC_GAME[akey]))
					return
			else:
				dw[akey] = 0.0
		m.g["pic_dwell"] = dw
	# hidden back door: a secret underwater entrance that works even before the stars
	if not explicit_touch and m.g.has("back_entry"):
		var bpos: Vector3 = m.g["back_entry"]
		if bpos.distance_to(ppos) < 9.0:
			m._enter_castle_interior(true)   # secret hatch -> Daddy's treasure room
			return
	# owner request 2026-07-21 (UI declutter): free-roam objective banners are
	# gone — the sparkle trail + voice lines already carry the route. Blanking
	# per tick keeps the old overwrite semantics (no stale hint can linger).
	m.hud_game.text = ""
	if m.l2_open and not explicit_touch:
		# magnet toward the fixed doorway (the door itself slides up out of view)
		var entry: Vector3 = m.g.get("entry", m.l2_door.position)
		var dd: float = Vector2(entry.x - ppos.x, entry.z - ppos.z).length()
		if dd < 36.0:
			var pull: Vector3 = entry + Vector3(0, 2, 10)
			m.player.position = m.player.position.lerp(pull, minf(0.75, delta * 1.5 * (1.0 - dd / 36.0)))
		if dd < 20.0:
			m._enter_castle_interior()

func handle_touch(screen_pos: Vector2) -> bool:
	if not (m.g.get("lagoon_play_anim", {}) as Dictionary).is_empty():
		return true
	var animal: Dictionary = _animal_at(screen_pos)
	if not animal.is_empty():
		_startle_animal(animal)
		return true
	var target: Dictionary = _target_at(screen_pos)
	if target.is_empty():
		_clear_focus()
		_set_walk_goal(screen_pos)
		return true
	m.g["lagoon_walk_goal_master"] = null
	var target_id: String = String(target.get("id", ""))
	if String(m.g.get("lagoon_promenade_focus", "")) == target_id:
		_activate(target)
		_clear_focus()
	else:
		_focus(target)
	return true

func _target_at(screen_pos: Vector2) -> Dictionary:
	var best: Dictionary = {}
	var best_distance: float = INF
	for value: Variant in m.g.get("lagoon_promenade_targets", []) as Array:
		var target: Dictionary = value as Dictionary
		var node: Node2D = target.get("node") as Node2D
		if node == null or not is_instance_valid(node):
			continue
		var distance: float = screen_from_master(node.position).distance_to(screen_pos)
		if distance <= float(target.get("radius_px", 110.0)) and distance < best_distance:
			best = target
			best_distance = distance
	return best

func _tick_slide_animation(card: Sprite2D, slide: Node2D, timer: float) -> void:
	if timer < 2.55:
		var progress: float = clampf(timer / 2.55, 0.0, 1.0)
		_set_play_frame(int(floor(progress * 5.0)) % 2)
		card.position = slide.position + Vector2(-135.0 + progress * 65.0,
			95.0 - progress * 435.0 - sin(progress * 5.0 * PI) * 18.0)
		card.rotation = 0.03
	elif timer < 3.15:
		_set_play_frame(2)
		var settle: float = smoothstep(0.0, 1.0, (timer - 2.55) / 0.60)
		card.position = slide.position + Vector2(-70.0, -340.0).lerp(
			SLIDE_RIDE_START_MASTER, settle)
		card.rotation = lerpf(0.03, 0.12, settle)
	else:
		_set_play_frame(3)
		var ride: float = smoothstep(0.0, 1.0, clampf((timer - 3.15) / 2.05, 0.0, 1.0))
		var first: Vector2 = SLIDE_RIDE_START_MASTER.lerp(SLIDE_RIDE_CONTROL_MASTER, ride)
		var second: Vector2 = SLIDE_RIDE_CONTROL_MASTER.lerp(SLIDE_RIDE_FINISH_MASTER, ride)
		card.position = slide.position + first.lerp(second, ride)
		card.rotation = lerpf(0.12, 0.42, ride)

func _populate_touch_interactables() -> void:
	touch_interactables.clear()
	if not touch_uses_explicit_interactions() or player == null:
		return
	if game == "north":
		var north_return: Vector3 = g.get("north_return_pos", Vector3.ZERO)
		if north_return != Vector3.ZERO:
			_touch_add_item("north:return", "Magic Cave Home", north_return, null, 9.0, 42.0, "ENTER")
		return
	if game != "level2":
		return
	if String(g.get("phase", "")) == "promenade":
		return
	if String(g.get("phase", "court")) == "hall":
		# The castle room stage owns every interior touch target. Never rebuild
		# the retired free-roaming hall's world-space interaction list behind it.
		return
	else:
		_populate_courtyard_touch_interactables()

func _populate_courtyard_touch_interactables() -> void:
	var kingdom_gates: Array = g.get("ocean_kingdom_gates", [])
	for gate_index in range(kingdom_gates.size()):
		var gate: Dictionary = kingdom_gates[gate_index]
		_touch_add_item(
			"court:ocean:%d" % gate_index,
			"Ocean Kingdom",
			gate.get("pos", Vector3.ZERO),
			gate.get("rune") as Node3D,
			9.0, 40.0, "ENTER", gate_index, true,
			InteractionAffordanceLogic.PLOT)
	if g.has("northern_portal_pos"):
		_touch_add_item("court:north", "Magic Cave", g["northern_portal_pos"],
			g.get("northern_portal_rune") as Node3D, 8.0, 38.0, "ENTER")
	if galaxy_unlocked and bw_portal_pos != Vector3.ZERO:
		_touch_add_item("court:galaxy", "Butterfly World", bw_portal_pos, null, 9.0, 38.0, "ENTER")
	if ember_portal_pos != Vector3.ZERO:
		_touch_add_item("court:ember", "Ember Fortress", ember_portal_pos, null, 10.0, 38.0, "ENTER")
	if kart_legA != Vector3.ZERO:
		_touch_add_item("court:kart_a", "Rainbow Race", kart_legA, null, 14.0, 42.0, "RACE")
		_touch_add_item("court:kart_b", "Reverse Rainbow Race", kart_legB, null, 14.0, 42.0, "RACE")
	for star_index in range(l2_stars.size()):
		var star_data: Dictionary = l2_stars[star_index]
		if bool(star_data.get("got", false)):
			continue
		var star_node: Node3D = star_data.get("node") as Node3D
		if is_instance_valid(star_node):
			_touch_add_item("court:star:%d" % star_index, "Dream Star", star_node.position,
				star_node, 14.0, 50.0, "GET", star_index, true,
				InteractionAffordanceLogic.PLOT)
	if l2_open:
		for picture_index in range(wall_pics.size()):
			var picture: Dictionary = wall_pics[picture_index]
			_touch_add_item("court:picture:%d" % picture_index, "Picture Game",
				picture.get("pos", Vector3.ZERO), picture.get("node") as Node3D,
				5.0, 24.0, "PLAY", picture_index)
	if g.has("back_entry"):
		_touch_add_item("court:back_entry", "Secret Castle Door", g["back_entry"], null, 9.0, 30.0, "ENTER")
	if l2_open and g.has("entry"):
		# Never track the l2_door NODE here: the slab slides ~30 units up into
		# the sky when the castle opens, dragging the ring/pick/approach with
		# it — a front-door tap then misses entirely (and could pick the SECRET
		# back hatch through the walls instead). Anchor the target on the
		# doorway itself at walk height, where the child actually taps.
		var castle_entry: Vector3 = g["entry"]
		if lagoon_floor:
			castle_entry.y = lagoon_walk_h(castle_entry.x, castle_entry.z) + 2.0
		_touch_add_item("court:castle", "Pearl Castle", castle_entry, null,
			20.0, 52.0, "ENTER", null, true,
			InteractionAffordanceLogic.PLOT)

func _touch_open_picture(picture_index: int) -> void:
	if picture_index < 0 or picture_index >= wall_pics.size():
		return
	var picture: Dictionary = wall_pics[picture_index]
	var art_key: String = String(picture.get("art", ""))
	if art_key == "p_slide":
		_l2_start_slide()
	elif PIC_GAME.has(art_key):
		_mg2d_open(String(PIC_GAME[art_key]))

func _lagoon_ref() -> SkyLagoon:
	if _sky_lagoon == null:
		_sky_lagoon = SkyLagoon.new(self)
	return _sky_lagoon

func _tick_level2(delta: float, ppos: Vector3) -> void:
	if String(g.get("phase", "")) == "promenade":
		_companion_ref().tick_canvas_care(delta)
		_lagoon_promenade_ref().tick(delta)
		return
	_lagoon_ref()._tick_level2(delta, ppos)

func _process(delta: float) -> void:
	# Legacy activity callbacks can restore an empty world ID. Once the authored
	# session starts, that ID must recover to Canvas before processing reef input.
	if _authored_world_session and game == "" and mg_kind == "" \
			and not start_menu_active and not intro_active:
		_exit_level2_now()
	_sync_pause_surface_layer()
	var slide_canvas_active: bool = _slide_canvas_fish_route_active()
	var slide_canvas_return_was_active: bool = _slide_canvas_return_guard_active()
	if slide_canvas_return_was_active:
		_tick_slide_canvas_return_guard()
	if not slide_canvas_active and not slide_canvas_return_was_active:
		_living_world_ref().tick(delta)
		if _fx_water != null:
			_fx_water.tick(delta)   # cutaways keep water FX; opaque fish Canvas suspends them
	# camera watchdog (CAMERA_AUDIT_2026_07 P0): if a torn-down mode freed the
	# current camera without restoring one (kart/galaxy teardown guards,
	# cancel(false) paths), fall back to Roshan instead of a black screen
	var vp_cam := active_viewport_camera()
	var sky_canvas_active: bool = game == "level2" \
		and String(g.get("phase", "")) == "promenade"
	var melody_canvas_active: bool = game == "melody"
	var fairy_conservatory_canvas_active: bool = game == "fairy_conservatory"
	var opaque_canvas_active: bool = sky_canvas_active or melody_canvas_active \
		or fairy_conservatory_canvas_active \
		or slide_canvas_active
	# Player creates its compatibility camera deferred during boot. Direct phone
	# entry can therefore reach Sky before that compatibility camera joins the tree; disarm
	# the late arrival as well as the synchronous entry path above.
	if slide_canvas_active and vp_cam != null and vp_cam.is_inside_tree():
		# Clear whichever camera actually owned the Viewport, not merely the
		# compatibility player camera. Exact ownership is restored on teardown.
		vp_cam.clear_current(false)
	elif opaque_canvas_active and player != null and player.cam != null \
			and player.cam.is_inside_tree() and player.cam.current:
		player.cam.clear_current(false)
	elif not opaque_canvas_active and vp_cam == null \
			and player != null and player.cam != null and player.cam.is_inside_tree():
		player.snap_cam()
		player.cam.make_current()
	if save_dirty:
		save_retry_t -= delta
		if save_retry_t <= 0.0:
			_write_save()
	elif save_pending:
		save_pending_age += maxf(delta, 0.0)
		save_pending_t -= delta
		if save_pending_t <= 0.0 or save_pending_age > 4.0:
			_write_save()
	_audio_ref().tick_dialogue(delta)
	_audio_ref().tick_voice()
	if msg_timer > 0.0:
		msg_timer -= delta
		if msg_timer <= 0.0:
			hud_msg.text = ""
	if hud_msg != null:
		hud_msg.visible = hud_msg.text != ""
	_sync_castle_voice_caption()
	if hud_game != null:
		# Activity-specific picture HUDs own their own surfaces; this legacy
		# free-roam sentence card is intentionally never persistent.
		hud_game.visible = false
	if pose_t >= 0.0:
		pose_t -= delta   # trophy curtain-call countdown (player frozen while >=0)
	_tick_contact_shadow()
	_tick_ambience_duck(delta)
	if mic_sys != null:
		mic_sys.tick(delta)   # no-op unless a battle armed the microphone
	if slide_canvas_return_was_active:
		_neutralize_slide_canvas_overlay_poll()
	elif slide_canvas_active and (_slide_canvas_input_context_blocks_input() \
			or _slide_canvas_overlay_axis_wait_neutral):
		_neutralize_slide_canvas_overlay_poll()
	else:
		_tick_overlay_pads(delta)
		_tick_pad_cursor(delta)
	if fps_lbl != null and pause_panel != null and pause_panel.visible:
		fps_lbl.text = "FPS: %d   (%s)" % [Engine.get_frames_per_second(), quality]
	if speech_t > 0.0:
		speech_t -= delta
		if speech_t <= 0.0 and speech_layer != null:
			speech_layer.visible = false
	if player == null:
		return
	if intro_active or day_two_transition_active:
		return
	if slide_canvas_return_was_active:
		# Even the second neutral sample is a quarantine frame. The controls block
		# may retire above, but the returned world cannot consume a level until a
		# genuinely fresh event arrives on a later frame.
		return
	var ppos: Vector3 = player.position
	if melody_canvas_active:
		# Melody owns the complete visible and interactive world. Preserve the
		# shared save/audio/pause work above, tick its controller exactly once,
		# and suspend every hidden spatial system until synchronous teardown.
		if touch_ui != null:
			touch_ui.set_action_label("PLAY")
		# Some platforms continue producing frames between focus-out/paused and
		# resumed/focus-in. Those frames are not gameplay time and cannot advance
		# Melody's medal clock, motion, neutral guard, or controller state.
		if _melody_input_context_lost():
			return
		_tick_game(delta)
		return
	if slide_canvas_active:
		# Harper and Fiona's fish slide is a complete Canvas world. Keep the shared
		# save/audio/pause seams above, but suspend every hidden Reef system and
		# tick its controller exactly once through _tick_game (after g.t advances).
		var slide_canvas := _game_obj("race", SlideRaceGame) as SlideRaceGame
		slide_canvas.refresh_canvas_layout()
		if _slide_canvas_input_context_lost():
			return
		if _slide_canvas_overlay_axis_wait_neutral:
			# Restore the controller's source-free boundary without advancing g.t,
			# then keep the ride frozen until two trustworthy neutral polls retire
			# every held overlay/gamepad source.
			slide_canvas.retire_input_context_restore_guard()
			return
		# Sticker Book and the other full-screen overlays resume SceneTree so their
		# own UI can animate. They must nevertheless freeze the ride itself: a
		# previously latched steer may never finish or award the game behind them.
		if _slide_canvas_overlay_owns_input():
			# Context restoration normally spends one source-free controller tick.
			# An overlay suppresses that tick, so retire only the guard here without
			# advancing g.t/progress; otherwise its own visible Back button deadlocks.
			slide_canvas.retire_input_context_restore_guard()
			return
		_tick_game(delta)
		return
	if sky_canvas_active:
		# The opaque Canvas promenade is a complete world slice. Its controller
		# is the sole movement, camera, interaction, collection and proximity
		# owner; the hidden player is only a legacy return coordinate.
		g["t"] = float(g.get("t", 0.0)) + delta
		_companion_ref().tick_canvas_care(delta)
		_lagoon_promenade_ref().tick(delta)
		if touch_ui != null:
			touch_ui.set_action_label(_lagoon_promenade_ref().action_label())
		return
	if touch_uses_explicit_interactions():
		_tap_move_ref().tick(delta)
		_interaction_ref().tick(delta, ppos)
	_collection_ref().tick(delta, ppos)
	# KartGame owns the visible scene and input while racing. Keep the small
	# global timer/audio work above, but suspend hidden reef collectibles,
	# characters, foliage, movers and culling instead of paying for two worlds.
	if game == "kart":
		if touch_ui != null and kart_game != null and kart_game.has_method("action_label"):
			touch_ui.set_action_label(String(kart_game.action_label()))
		return
	if game == "level2":
		g["t"] = float(g["t"]) + delta
		_tick_level2(delta, ppos)
	elif game == "north":
		_tick_northern(delta, ppos)
	elif game == "galaxy":
		pass   # the GalaxyLevel node ticks itself
	elif game == "chapter2_lawn":
		if is_instance_valid(chapter2_lawn_view):
			chapter2_lawn_view.tick(delta)
	elif game == "fairy_conservatory":
		if fairy_conservatory_handoff != null \
				and is_instance_valid(fairy_conservatory_handoff) \
				and fairy_conservatory_handoff.has_method("tick"):
			fairy_conservatory_handoff.call("tick", delta)
	elif game == "ember":
		pass   # the EmberFortressLevel node ticks itself
	elif game == "combat":
		pass   # the CombatArena node owns movement, camera and encounter logic
	elif game == "stuffie":
		pass   # the StuffieBattle node owns the creature, camera and dodge QTE
	elif game == "dungeon" or game == "emberdun":
		pass   # DungeonLevel sequences the battles and visual puzzles
	elif game == "opera":
		pass   # OperaHouse sequences the thirteen Canvas career shows
	elif game == "kitchen_cooking":
		pass   # The fridge portal's OperaAct owns the cooking gesture chain
	elif game != "":
		_tick_game(delta)
	_tick_wall_fade(delta)
	_companion_ref().tick(delta)
	_tick_beans(delta)
	cull_timer -= delta
	if cull_timer <= 0.0:
		cull_timer = 0.7
		var lim: float = 95.0 if quality == "speedy" else 160.0
		for i3 in range(anim_cull.size() - 1, -1, -1):
			var ac: Dictionary = anim_cull[i3]
			if not is_instance_valid(ac["node"]) or not is_instance_valid(ac["ap"]):
				anim_cull.remove_at(i3)
				continue
			var nd: Node3D = ac["node"]
			var ap2: AnimationPlayer = ac["ap"]
			var near: bool = nd.position.distance_to(ppos) < lim
			if near and not ap2.is_playing():
				ap2.play()
			elif not near and ap2.is_playing():
				ap2.pause()
	if touch_ui != null:
		var act_lbl := "JUMP"
		if game == "level2" and String(g.get("phase", "")) == "promenade":
			act_lbl = _lagoon_promenade_ref().action_label()
		elif touch_uses_explicit_interactions() and touch_focus_ready:
			for touch_item_value: Variant in touch_interactables:
				var touch_item: Dictionary = touch_item_value as Dictionary
				if String(touch_item.get("id", "")) == touch_focus_id:
					act_lbl = String(touch_item.get("verb", "GO"))
					break
		elif _collection_ref().has_nearby():
			act_lbl = "CATCH!"
		elif game == "fetch" and String(g.get("phase", "")) == "aim":
			act_lbl = "THROW"
		elif game == "shop":
			act_lbl = "BUY"
		elif game == "fairyshoot":
			act_lbl = "SPARKLE"
		elif game == "kart" and kart_game != null and kart_game.has_method("action_label"):
			act_lbl = String(kart_game.action_label())   # GO! on the pick screens, TURBO in the race
		elif game == "combat" and combat_game != null:
			act_lbl = "ICE" if combat_game.kind == "ice" else "FIRE"
		elif game == "dustboss":
			act_lbl = String(_game_obj("dustboss", DustBossGame).action_label())
		elif game == "stuffie" and stuffie_game != null:
			act_lbl = stuffie_game.action_label()   # PECK / CLAW
		elif (game == "dungeon" or game == "emberdun") and dungeon_game != null:
			act_lbl = dungeon_game.action_label()
		elif game == "opera" and opera_game != null:
			act_lbl = opera_game.action_label()
		elif game == "kitchen_cooking":
			act_lbl = _castle_rooms_ref().kitchen_action_label()
		touch_ui.set_action_label(act_lbl)

